arguments.new_str:
using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

var mlContext = new MLContext(seed: 42);

var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
IDataView dataView = mlContext.Data.LoadFromTextFile<CustomerDataRaw>(dataPath, hasHeader: true, separatorChar: ',');

// Map "Yes"/"No" to boolean Label
var labelMapping = mlContext.Transforms.CustomMapping<CustomerDataRaw, ChurnLabel>(
    (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
    contractName: "ChurnMapping");

var pipeline = labelMapping
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerDataRaw.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerDataRaw.Age),
        nameof(CustomerDataRaw.Income),
        "RegionEncoded",
        nameof(CustomerDataRaw.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label",
        featureColumnName: "Features"));

// Cross-validate on small dataset instead of train/test split
var cvResults = mlContext.BinaryClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3, labelColumnName: "Label");
var avgAuc = cvResults.Average(r => r.Metrics.AreaUnderRocCurve);
var avgF1 = cvResults.Average(r => r.Metrics.F1Score);
var avgAcc = cvResults.Average(r => r.Metrics.Accuracy);
Console.WriteLine($"Cross-Validation — AUC: {avgAuc:F4}, Accuracy: {avgAcc:F4}, F1: {avgF1:F4}");

// Train final model on all data
var model = pipeline.Fit(dataView);

var modelPath = Path.Combine(AppContext.BaseDirectory, "ChurnModel.zip");
mlContext.Model.Save(model, dataView.Schema, modelPath);

builder.Services.AddPredictionEnginePool<CustomerInput, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapPost("/predict", (PredictionEnginePool<CustomerInput, ChurnPrediction> pool, CustomerInput customer) =>
{
    var prediction = pool.Predict(customer);
    return Results.Ok(new
    {
        WillChurn = prediction.PredictedLabel,
        Probability = prediction.Probability
    });
});

app.Run();

